-- Table and column comments (backup 2026-07-16). Several are load-bearing documentation.

COMMENT ON COLUMN public.cron_logs.completed_at IS 'Timestamp when the cron job completed (NULL if still running or crashed)';
COMMENT ON COLUMN public.cron_logs.errors IS 'Array of error messages encountered during execution';
COMMENT ON COLUMN public.cron_logs.job_name IS 'Name of the cron job (e.g., send-reminders, update-expired-status)';
COMMENT ON COLUMN public.cron_logs.started_at IS 'Timestamp when the cron job started execution';
COMMENT ON COLUMN public.cron_logs.status IS 'Job status: running, success, or failure';
COMMENT ON COLUMN public.cron_logs.summary IS 'JSON summary of job execution (e.g., {totalUpdated: 5, totalSent: 10})';
COMMENT ON COLUMN public.discounts.discount_percentage IS 'Discount percentage (1-100)';
COMMENT ON COLUMN public.discounts.is_active IS 'Whether this discount is available for use';
COMMENT ON COLUMN public.email_confirmations.expires_at IS 'Token expiry time (24 hours from creation)';
COMMENT ON COLUMN public.email_confirmations.ip_address IS 'IP address from which the confirmation was requested (for security auditing)';
COMMENT ON COLUMN public.email_confirmations.status IS 'pending: awaiting confirmation, confirmed: email verified, expired: token expired';
COMMENT ON COLUMN public.email_confirmations.token IS 'SHA-256 hash of the confirmation token sent via email';
COMMENT ON COLUMN public.email_confirmations.user_agent IS 'User agent string from confirmation request (for security auditing)';
COMMENT ON COLUMN public.gyms.current_period_end IS 'Paid-through boundary; always set from the DB clock via save_gym_subscription()';
COMMENT ON COLUMN public.gyms.email_verified IS 'Indicates if the email has been verified via Supabase Auth';
COMMENT ON COLUMN public.gyms.member_count IS 'Denormalized count of ACTIVE members only (trigger-maintained). Non-active members are not counted and never quota-gated.';
COMMENT ON COLUMN public.gyms.next_charge_at IS 'When the charge-renewals cron next charges this gym''s stored token (NULL = nothing scheduled: legacy recurring, trialing, canceled, suspended, complimentary). Maintained by save_gym_subscription / schedule_charge_retry / the dunning + trial crons on the DB clock.';
COMMENT ON COLUMN public.gyms.phone_number IS 'Optional phone number in +94 format for OTP login';
COMMENT ON COLUMN public.gyms.profile_image_url IS 'Profile image stored as SVG data URL';
COMMENT ON COLUMN public.gyms.subscription_status IS 'SaaS billing status (trialing|active|past_due|suspended|canceled). Mirror: SubscriptionConfig.ts SaasStatus';
COMMENT ON COLUMN public.gyms.subscription_tier IS 'SaaS billing tier (lite|pro|enterprise — all paid). Mirror: SubscriptionConfig.ts SaasTier';
COMMENT ON COLUMN public.gyms.trial_ends_at IS 'Trial-window boundary (TRIAL_PERIOD_DAYS = 14, SubscriptionConfig.ts). Set by DEFAULT at signup; meaningful while subscription_status = trialing. The trial-expiry cron (20260708000006) suspends trialing gyms past it.';
COMMENT ON COLUMN public.gyms.user_id IS 'References the authenticated user from Supabase Auth';
COMMENT ON COLUMN public.members.discount_id IS 'Optional reference to discount preset';
COMMENT ON COLUMN public.members.gym_id IS 'References the gym this member belongs to';
COMMENT ON COLUMN public.members.membership_start_date IS 'Actual date when the membership started (can be backdated)';
COMMENT ON COLUMN public.members.next_due_date IS 'Date when next payment is due';
COMMENT ON COLUMN public.members.phone_number IS 'Phone number in +94 format for SMS notifications';
COMMENT ON COLUMN public.members.plan_amount IS 'Monthly payment amount in LKR';
COMMENT ON COLUMN public.members.plan_type IS 'Member plan type (must match a plan_type in plan_types table for their gym)';
COMMENT ON COLUMN public.members.recurring_discount IS 'Whether discount applies to all future payments';
COMMENT ON COLUMN public.members.registered_date IS 'Date when the member record was created in the system (for backdated members, this may be after membership_start_date)';
COMMENT ON COLUMN public.members.status IS 'Current membership status: active, expired, suspended, or cancelled';
COMMENT ON COLUMN public.otp_tokens.expires_at IS 'OTP expiry time (10 minutes from creation for improved UX)';
COMMENT ON COLUMN public.otp_tokens.otp_code IS 'Six-digit OTP code (bcrypt hashed with 10 salt rounds for security)';
COMMENT ON COLUMN public.otp_tokens.used IS 'Whether this OTP has been used';
COMMENT ON COLUMN public.payments.amount_paid IS 'Actual amount paid in LKR (after discount)';
COMMENT ON COLUMN public.payments.discount_applied IS 'Name of discount applied (snapshot)';
COMMENT ON COLUMN public.payments.discount_percentage IS 'Discount percentage at time of payment (snapshot)';
COMMENT ON COLUMN public.payments.gym_id IS 'References the gym this payment belongs to (multi-tenant isolation)';
COMMENT ON COLUMN public.payments.member_id IS 'References the member who made this payment';
COMMENT ON COLUMN public.payments.next_due_date_calculated IS 'Next due date calculated at time of payment';
COMMENT ON COLUMN public.plan_types.default_amount IS 'Default amount in LKR for this plan type';
COMMENT ON COLUMN public.plan_types.is_active IS 'Whether this plan type is available for new members';
COMMENT ON COLUMN public.plan_types.plan_type IS 'Plan type identifier (e.g., monthly, daily, annual, quarterly, weekly, etc.). Lowercase alphanumeric with hyphens/underscores allowed.';
COMMENT ON COLUMN public.sms_logs.delivery_status IS 'Delivery status: sent, delivered, or failed';
COMMENT ON COLUMN public.sms_logs.error_message IS 'Error message from SMS provider if delivery failed (NULL for successful deliveries)';
COMMENT ON COLUMN public.sms_logs.sms_type IS 'Type of SMS: reminder (7-day, 3-day, due today, overdue) or receipt';
COMMENT ON COLUMN public.sms_logs.text_lk_message_id IS 'Message ID from text.lk API (null for mock SMS)';
COMMENT ON TABLE public.checkout_intents IS 'Pending PayHere checkout attribution: webhook resolves order_id -> gym. Server-side plumbing; no gym-owner RLS policy.';
COMMENT ON TABLE public.cron_logs IS 'Audit log for cron job executions';
COMMENT ON TABLE public.discounts IS 'Stores discount presets per gym';
COMMENT ON TABLE public.email_confirmations IS 'Tracks email confirmation attempts and status for gym registrations';
COMMENT ON TABLE public.gyms IS 'Stores gym/business information for each registered gym owner. Links to auth.users for authentication.';
COMMENT ON TABLE public.members IS 'Stores gym members/customers with their membership details (emergency contact fields removed 2026-02-27)';
COMMENT ON TABLE public.otp_tokens IS 'Stores OTP tokens for phone-based authentication (60-second expiry)';
COMMENT ON TABLE public.payments IS 'Stores payment history for all members. Discount details are snapshotted at payment time.';
COMMENT ON TABLE public.plan_types IS 'Stores plan type configurations per gym (monthly, daily, annual)';
COMMENT ON TABLE public.saas_admins IS 'Platform-operator allow-list gating /system-health + /api/admin/*. Session + membership here replaces the retired NEXT_PUBLIC_ADMIN_API_SECRET. Provision by inserting a user_id (service role / dashboard SQL) — see docs/DEPLOYMENT_PAYHERE_CHECKLIST.md.';
COMMENT ON TABLE public.saas_charge_attempts IS 'Ledger of server-initiated PayHere token charges (Charging API). Pending row inserted BEFORE the REST call: webhook order_id resolution, timeout-ambiguity recovery, and the one-pending-per-gym concurrency gate. Server-side plumbing; no gym-owner RLS policy.';
COMMENT ON TABLE public.saas_payment_logs IS 'PayHere webhook audit + idempotency anchor + gym billing history. raw_payload stores md5sig REDACTED (load-bearing for replay defense, plan C-24).';
COMMENT ON TABLE public.sms_logs IS 'Stores SMS delivery logs for tracking reminders and receipts';
